import{_ as p,a0 as t,w as o,s as d,I as n,x as e,a1 as i,A as l,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何裝載/卸載 Linux 內核模組 | LCTT x X-CMD","titleTemplate":false,"description":"如何裝載/卸載 Linux 內核模組 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何裝載/卸載 Linux 內核模組 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何裝載/卸載 Linux 內核模組 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180530 How to load or unload a Linux kernel module","title":"如何裝載/卸載 Linux 內核模組","tag":"201806","desc":""},"relativePath":"201806/20180530 How to load or unload a Linux kernel module.md","filePath":"[post].md"}'),u={name:"201806/20180530 How to load or unload a Linux kernel module.md"};function c(h,s,k,g,b,m){const a=t("Link");return o(),d("div",null,[s[18]||(s[18]=n("h1",{id:"如何裝載-卸載-linux-內核模組",tabindex:"-1"},[e("如何裝載/卸載 Linux 內核模組 "),n("a",{class:"header-anchor",href:"#如何裝載-卸載-linux-內核模組","aria-label":"Permalink to “如何裝載/卸載 Linux 內核模組”"},"​")],-1)),s[19]||(s[19]=n("blockquote",null,[n("p",null,"找到並裝載內核模組以解決外設問題。")],-1)),s[20]||(s[20]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/code_computer_development_programming.png?itok=4OM29-82",alt:""})],-1)),n("p",null,[s[1]||(s[1]=e("本文來自 Manning 出版的 ",-1)),i(a,{href:"https://www.manning.com/books/linux-in-action?a_aid=bootstrap-it&a_bid=4ca15fc9&chan=opensource"},{default:l(()=>[...s[0]||(s[0]=[e("Linux in Action",-1)])]),_:1}),s[2]||(s[2]=e(" 的第 15 章。",-1))]),s[21]||(s[21]=r(`<p>Linux 使用內核模組管理硬件外設。 我們來看看它是如何工作的。</p><p>運行中的 Linux 內核是您不希望被破壞的東西之一。畢竟，內核是驅動計算機所做的一切工作的軟件。考慮到在一個運行的系統上必須同時管理諸多細節，最好能讓內核儘可能的減少分心，專心的完成它的工作。但是，如果對計算環境進行任何微小的更改都需要重啓整個系統，那麼插入一個新的網絡攝像頭或打印機就可能會嚴重影響您的工作流程。每次添加設備時都必須重新啓動，以使系統識別它，這效率很低。</p><p>為了在穩定性和可用性之間達成有效的平衡，Linux 將內核隔離，但是允許您通過可加載內核模組 (LKM) 實時添加特定的功能。如下圖所示，您可以將模組視為軟件的一部分，它告訴內核在哪裏找到一個設備以及如何使用它。反過來，內核使設備對用户和進程可用，並監視其操作。</p><p><img src="https://opensource.com/sites/default/files/uploads/kernels.png" alt="Kernel modules" title="Kernel modules"></p><p><em>內核模組充當設備和 Linux 內核之間的轉換器。</em></p><p>雖然你可以自己編寫模組來完全按照你喜歡的方式來支持一個設備，但是為什麼要這樣做呢？Linux 模組庫已經非常強大，通常不需要自己去實現一個模組。 而絕大多數時候，Linux 會自動加載新設備的模組，而您甚至不知道它。</p><p>不過，有時候，出於某種原因，它本身並不會自動進行。（你肯定不想讓那個招聘經理不耐煩地一直等待你的笑臉加入視頻面試。）為了幫助你解決問題，你需要更多地瞭解內核模組，特別是，如何找到運行你的外設的實際模組，然後如何手動激活它。</p><h3 id="查找內核模組" tabindex="-1">查找內核模組 <a class="header-anchor" href="#查找內核模組" aria-label="Permalink to “查找內核模組”">​</a></h3><p>按照公認的約定，內核模組是位於 <code>/lib/modules/</code> 目錄下的具有 .ko（內核對象）擴展名的文件。 然而，在你找到這些文件之前，你還需要選擇一下。因為在引導時你需要從版本列表中選擇其一加載，所以支持您選擇的特定軟件（包括內核模組）必須存在某處。 那麼，<code>/lib/modules/</code> 就是其中之一。 你會發現目錄裏充滿了每個可用的 Linux 內核版本的模組; 例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /lib/modules</span></span>
<span class="line"><span>4.4.0-101-generic</span></span>
<span class="line"><span>4.4.0-103-generic</span></span>
<span class="line"><span>4.4.0-104-generic</span></span></code></pre></div><p>在我的電腦上，運行的內核是版本號最高的版本（4.4.0-104-generic），但不能保證這對你來説是一樣的（內核經常更新）。 如果您將要在一個運行的系統上使用模組完成一些工作的話，你需要確保您找到正確的目錄樹。</p><p>好消息：有一個可靠的竅門。相對於通過名稱來識別目錄，並希望能夠找到正確的目錄，你可以使用始終指向使用的內核名稱的系統變量。 您可以使用 <code>uname -r</code>（ <code>-r</code> 從系統信息中指定通常顯示的內核版本號）來調用該變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -r</span></span>
<span class="line"><span>4.4.0-104-generic</span></span></code></pre></div><p>通過這些信息，您可以使用稱為命令替換的過程將 <code>uname</code> 併入您的文件系統引用中。 例如，要導航到正確的目錄，您需要將其添加到 <code>/lib/modules</code> 。 要告訴 Linux “uname” 不是一個文件系統中的位置，請將 <code>uname</code> 部分用反引號括起來，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /lib/modules/\`uname -r\`</span></span>
<span class="line"><span>build   modules.alias        modules.dep      modules.softdep</span></span>
<span class="line"><span>initrd  modules.alias.bin    modules.dep.bin  modules.symbols</span></span>
<span class="line"><span>kernel  modules.builtin      modules.devname  modules.symbols.bin</span></span>
<span class="line"><span>misc    modules.builtin.bin  modules.order    vdso</span></span></code></pre></div><p>你可以在 <code>kernel/</code> 目錄下的子目錄中找到大部分模組。 花幾分鐘時間瀏覽這些目錄，瞭解事物的排列方式和可用內容。 這些文件名通常會讓你知道它們是什麼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /lib/modules/\`uname -r\`/kernel</span></span>
<span class="line"><span>arch  crypto  drivers  fs  kernel  lib  mm </span></span>
<span class="line"><span>net  sound  ubuntu  virt  zfs</span></span></code></pre></div><p>這是查找內核模組的一種方法；實際上，這是一種快速的方式。 但這不是唯一的方法。 如果你想獲得完整的集合，你可以使用 <code>lsmod</code> 列出所有當前加載的模組以及一些基本信息。 這個截斷輸出的第一列（在這裏列出的太多了）是模組名稱，後面是文件大小和數量，然後是每個模組的名稱：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsmod</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>vboxdrv          454656  3 vboxnetadp,vboxnetflt,vboxpci</span></span>
<span class="line"><span>rt2x00usb        24576  1 rt2800usb</span></span>
<span class="line"><span>rt2800lib        94208  1 rt2800usb</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>到底有多少？好吧，我們再運行一次 <code>lsmod </code> ，但是這一次將輸出管道輸送到 <code>wc -l</code> 看一下一共多少行:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsmod | wc -l</span></span>
<span class="line"><span>113</span></span></code></pre></div><p>這是已加載的模組。 總共有多少個？ 運行 <code>modprobe -c</code> 並計算這些行將給我們這個數字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ modprobe -c | wc -l</span></span>
<span class="line"><span>33350</span></span></code></pre></div><p>有 33,350 個可用模組！？ 看起來好像有人多年來一直在努力為我們提供軟件來驅動我們的物理設備。</p><p>注意：在某些系統中，您可能會遇到自定義的模組，這些模組要麼在 <code>/etc/modules</code> 文件中使用獨特的條目進行引用，要麼在 <code>/etc/modules-load.d/</code> 下的配置文件中。這些模組很可能是本地開發項目的產物，可能涉及前沿實驗。不管怎樣，知道你看到的是什麼總是好的。</p><p>這就是如何找到模組的方法。 如果出於某種原因，它不會自行加載，您的下一個工作就是弄清楚如何手動加載未激活的模組。</p><h3 id="手動加載內核模組" tabindex="-1">手動加載內核模組 <a class="header-anchor" href="#手動加載內核模組" aria-label="Permalink to “手動加載內核模組”">​</a></h3><p>在加載內核模組之前，邏輯上您必須確認它存在。在這之前，你需要知道它叫什麼。要做到這一點，有時需要兼有魔法和運氣以及在線文檔作者的辛勤工作的幫助。</p><p>我將通過描述一段時間前遇到的問題來説明這個過程。在一個晴朗的日子裏，出於某種原因，筆記本電腦上的 WiFi 接口停止工作了。就這樣。也許是軟件升級把它搞砸了。誰知道呢？我運行了 <code>lshw -c network</code> ，得到了這個非常奇怪的信息:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>network UNCLAIMED</span></span>
<span class="line"><span>    AR9485 Wireless Network Adapter</span></span></code></pre></div><p>Linux 識別到了接口（Atheros AR9485），但將其列為未聲明。 那麼，正如他們所説的那樣，“當情況變得嚴峻時，就會在互聯網上進行艱難的搜索。” 我搜索了一下 atheros ar9 linux 模組，在瀏覽了一頁又一頁五年前甚至是十年前的頁面後，它們建議我自己寫個模組或者放棄吧，然後我終於發現（最起碼 Ubuntu 16.04）有一個可以工作的模組。 它的名字是 ath9k 。</p><p>是的! 這場戰鬥勝券在握！向內核添加模組比聽起來容易得多。 要仔細檢查它是否可用，可以針對模組的目錄樹運行 <code>find</code>，指定 <code>-type f</code> 來告訴 Linux 您正在查找文件，然後將字符串 <code>ath9k</code> 和星號一起添加以包含所有以你的字符串打頭的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find /lib/modules/$(uname -r) -type f -name ath9k*</span></span>
<span class="line"><span>/lib/modules/4.4.0-97-generic/kernel/drivers/net/wireless/ath/ath9k/ath9k_common.ko</span></span>
<span class="line"><span>/lib/modules/4.4.0-97-generic/kernel/drivers/net/wireless/ath/ath9k/ath9k.ko</span></span>
<span class="line"><span>/lib/modules/4.4.0-97-generic/kernel/drivers/net/wireless/ath/ath9k/ath9k_htc.ko</span></span>
<span class="line"><span>/lib/modules/4.4.0-97-generic/kernel/drivers/net/wireless/ath/ath9k/ath9k_hw.ko</span></span></code></pre></div><p>再一步，加載模組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># modprobe ath9k</span></span></code></pre></div><p>就是這樣。無啓動，沒煩惱。</p><p>這裏還有一個示例，向您展示如何使用已經崩潰的運行模組。曾經有一段時間，我使用羅技網絡攝像頭和一個特定的軟件會使攝像頭在下次系統啓動前無法被任何其他程序訪問。有時我需要在不同的應用程序中打開相機，但沒有時間關機重新啓動。（我運行了很多應用程序，在引導之後將它們全部準備好需要一些時間。）</p><p>由於這個模組可能是運行的，所以使用 <code>lsmod</code> 來搜索 video 這個詞應該給我一個關於相關模組名稱的提示。 實際上，它比提示更好：用 video 這個詞描述的唯一模組是 uvcvideo（如下所示）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsmod | grep video</span></span>
<span class="line"><span>uvcvideo               90112  0</span></span>
<span class="line"><span>videobuf2_vmalloc      16384  1 uvcvideo</span></span>
<span class="line"><span>videobuf2_v4l2         28672  1 uvcvideo</span></span>
<span class="line"><span>videobuf2_core         36864  2 uvcvideo,videobuf2_v4l2</span></span>
<span class="line"><span>videodev              176128  4 uvcvideo,v4l2_common,videobuf2_core,videobuf2_v4l2</span></span>
<span class="line"><span>media                  24576  2 uvcvideo,videodev</span></span></code></pre></div><p>有可能是我自己的操作導致了崩潰，我想我可以挖掘更深一點，看看我能否以正確的方式解決問題。但結果你知道的；有時你不關心理論，只想讓設備工作。 所以我用 <code>rmmod</code> 殺死了 <code>uvcvideo</code> 模組，然後用 <code>modprobe</code> 重新啓動它，一切都好：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># rmmod uvcvideo</span></span>
<span class="line"><span># modprobe uvcvideo</span></span></code></pre></div><p>再一次：不重新啓動。沒有其他的後續影響。</p><hr>`,43)),n("p",null,[s[4]||(s[4]=e("via: ",-1)),i(a,{href:"https://opensource.com/article/18/5/how-load-or-unload-linux-kernel-module"},{default:l(()=>[...s[3]||(s[3]=[e("https://opensource.com/article/18/5/how-load-or-unload-linux-kernel-module",-1)])]),_:1})]),n("p",null,[s[9]||(s[9]=e("作者：",-1)),i(a,{href:"https://opensource.com/users/dbclinton"},{default:l(()=>[...s[5]||(s[5]=[e("David Clinton",-1)])]),_:1}),s[10]||(s[10]=e(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 譯者：",-1)),i(a,{href:"https://github.com/amwps290"},{default:l(()=>[...s[7]||(s[7]=[e("amwps290",-1)])]),_:1}),s[12]||(s[12]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:l(()=>[...s[14]||(s[14]=[e("Linux中國",-1)])]),_:1}),s[17]||(s[17]=e(" 榮譽推出",-1))])])}const y=p(u,[["render",c]]);export{x as __pageData,y as default};
